namespace Typhon.Stdlib
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.IO;
    using System.Linq;
    using Typhon.Runtime;

    /// <summary>shutil: high-level file operations.</summary>
    internal static class shutil
    {
        /// <summary>shutil.Error: an OSError.</summary>
        internal class Error : IOException { public Error(string message) : base(message) { } }
        /// <summary>shutil.SameFileError: source and destination are the same file.</summary>
        internal sealed class SameFileError : Error { public SameFileError(string message) : base(message) { } }

        static string Q(string p) => Builtins.repr(p);
        static FileNotFoundException NotFound(string p) => new FileNotFoundException($"[Errno 2] No such file or directory: {Q(p)}", p);
        static IOException IsADirectory(string p) => new IOException($"[Errno 21] Is a directory: {Q(p)}");
        static IOException NotADirectory(string p) => new IOException($"[Errno 20] Not a directory: {Q(p)}");
        static IOException FileExists(string p) => new IOException($"[Errno 17] File exists: {Q(p)}");

        /// <summary>A path argument: a str or an os.PathLike (pathlib.Path).</summary>
        static string P(object path) => path as string ?? path?.ToString() ?? throw new InvalidCastException("expected str, bytes or os.PathLike object, not NoneType");

        static bool IsLink(string p) { try { return new FileInfo(p).LinkTarget != null; } catch (Exception) { return false; } }
        static bool Exists(string p) => File.Exists(p) || Directory.Exists(p);

        static bool SameFile(string a, string b)
        {
            if (!Exists(a) || !Exists(b)) return false;
            string Real(string p) { try { return System.IO.Path.GetFullPath(new FileInfo(p).ResolveLinkTarget(true)?.FullName ?? p); } catch (Exception) { return System.IO.Path.GetFullPath(p); } }
            return string.Equals(Real(a), Real(b), OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);
        }

        static string Basename(string p) => System.IO.Path.GetFileName(p.TrimEnd('/', System.IO.Path.DirectorySeparatorChar));

        // ── copying files ──

        public static string copyfile(object src, object dst, bool follow_symlinks = true)
        {
            string s = P(src), d = P(dst);
            if (SameFile(s, d)) throw new SameFileError($"{Q(s)} and {Q(d)} are the same file");
            if (!follow_symlinks && IsLink(s))
            {
                File.CreateSymbolicLink(d, new FileInfo(s).LinkTarget!);
                return d;
            }
            if (Directory.Exists(s)) throw IsADirectory(s);
            if (!File.Exists(s)) throw NotFound(s);
            if (Directory.Exists(d)) throw IsADirectory(d);
            string? parent = System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(d));
            if (parent != null && !Directory.Exists(parent)) throw NotFound(d);
            File.Copy(s, d, overwrite: true);
            return d;
        }

        public static void copymode(object src, object dst, bool follow_symlinks = true)
        {
            string s = P(src), d = P(dst);
            if (!Exists(s)) throw NotFound(s);
            if (!OperatingSystem.IsWindows()) File.SetUnixFileMode(d, File.GetUnixFileMode(s));
            else File.SetAttributes(d, (File.GetAttributes(d) & ~FileAttributes.ReadOnly) | (File.GetAttributes(s) & FileAttributes.ReadOnly));
        }

        public static void copystat(object src, object dst, bool follow_symlinks = true)
        {
            string s = P(src), d = P(dst);
            if (!Exists(s)) throw NotFound(s);
            bool dir = Directory.Exists(d);
            if (!OperatingSystem.IsWindows()) File.SetUnixFileMode(d, File.GetUnixFileMode(s));
            if (dir)
            {
                Directory.SetLastAccessTimeUtc(d, Directory.GetLastAccessTimeUtc(s));
                Directory.SetLastWriteTimeUtc(d, Directory.GetLastWriteTimeUtc(s));
            }
            else
            {
                File.SetLastAccessTimeUtc(d, File.GetLastAccessTimeUtc(s));
                File.SetLastWriteTimeUtc(d, File.GetLastWriteTimeUtc(s));
            }
        }

        /// <summary>copy: the data and the permission bits; into a directory under the source's name.</summary>
        public static string copy(object src, object dst, bool follow_symlinks = true)
        {
            string s = P(src), d = P(dst);
            if (Directory.Exists(d)) d = Globber.PathJoin(d, System.IO.Path.GetFileName(s));
            copyfile(s, d, follow_symlinks);
            copymode(s, d, follow_symlinks);
            return d;
        }

        /// <summary>copy2: like copy, and the timestamps too.</summary>
        public static string copy2(object src, object dst, bool follow_symlinks = true)
        {
            string s = P(src), d = P(dst);
            if (Directory.Exists(d)) d = Globber.PathJoin(d, System.IO.Path.GetFileName(s));
            copyfile(s, d, follow_symlinks);
            copystat(s, d, follow_symlinks);
            return d;
        }

        /// <summary>copyfileobj: copies the rest of one open file into another, in chunks.</summary>
        public static void copyfileobj(object fsrc, object fdst, long length = 0)
        {
            long n = length > 0 ? length : 64 * 1024;
            dynamic src = fsrc, dst = fdst;
            while (true)
            {
                object buf = src.read(n);
                if (Builtins.len(buf) == 0) break;
                dst.write((dynamic)buf);
            }
        }

        // ── trees ──

        /// <summary>ignore_patterns: an ignore function for copytree that drops the names matching any of the patterns.</summary>
        public static Func<string, List<string>, IEnumerable<string>> ignore_patterns(params string[] patterns) =>
            (path, names) => new HashSet<string>(names.Where(n => patterns.Any(p => FnPattern.FnMatch(n, p))));

        public static string copytree(object src, object dst, bool symlinks = false, Func<string, List<string>, IEnumerable<string>>? ignore = null,
                                      Func<string, string, string>? copy_function = null, bool ignore_dangling_symlinks = false, bool dirs_exist_ok = false)
        {
            string s = P(src), d = P(dst);
            if (!Directory.Exists(s)) throw File.Exists(s) ? NotADirectory(s) : NotFound(s);
            var copyFn = copy_function ?? ((a, b) => copy2(a, b));
            var entries = Directory.EnumerateFileSystemEntries(s).Select(System.IO.Path.GetFileName).Select(x => x!).ToList();
            var ignored = ignore == null ? new HashSet<string>() : new HashSet<string>(ignore(s, entries));
            if (Directory.Exists(d) || File.Exists(d)) { if (!dirs_exist_ok || File.Exists(d)) throw FileExists(d); }
            else Directory.CreateDirectory(d);
            var errors = new List<(string, string, string)>();
            foreach (var name in entries)
            {
                if (ignored.Contains(name)) continue;
                string srcname = Globber.PathJoin(s, name), dstname = Globber.PathJoin(d, name);
                try
                {
                    if (IsLink(srcname))
                    {
                        string linkto = new FileInfo(srcname).LinkTarget!;
                        if (symlinks)
                        {
                            if (Directory.Exists(srcname)) Directory.CreateSymbolicLink(dstname, linkto);
                            else File.CreateSymbolicLink(dstname, linkto);
                            continue;
                        }
                        if (!Exists(srcname) && ignore_dangling_symlinks) continue;
                        if (Directory.Exists(srcname)) copytree(srcname, dstname, symlinks, ignore, copy_function, ignore_dangling_symlinks, dirs_exist_ok);
                        else copyFn(srcname, dstname);
                    }
                    else if (Directory.Exists(srcname)) copytree(srcname, dstname, symlinks, ignore, copy_function, ignore_dangling_symlinks, dirs_exist_ok);
                    else copyFn(srcname, dstname);
                }
                catch (Error err) { errors.Add((srcname, dstname, err.Message)); }
                catch (IOException why) { errors.Add((srcname, dstname, why.Message)); }
                catch (UnauthorizedAccessException why) { errors.Add((srcname, dstname, why.Message)); }
            }
            try { copystat(s, d); }
            catch (IOException why) { errors.Add((s, d, why.Message)); }
            if (errors.Count > 0) throw new Error("[" + string.Join(", ", errors.Select(e => $"({Q(e.Item1)}, {Q(e.Item2)}, {Q(e.Item3)})")) + "]");
            return d;
        }

        /// <summary>rmtree: deletes a directory and everything below it (symbolic links are removed, not followed).</summary>
        public static void rmtree(object path, bool ignore_errors = false, object? onerror = null,
            object? onexc = null, object? dir_fd = null, bool _onexc_kwargs = false)
        {
            if (dir_fd != null) throw new NotImplementedException("dir_fd unavailable for rmtree");
            string p = P(path);
            if (!ignore_errors && (onexc != null || onerror != null))
            {
                RemoveTreeWithHandler(p, onexc, onerror);
                return;
            }
            try
            {
                if (IsLink(p)) throw new IOException("Cannot call rmtree on a symbolic link");
                if (!Directory.Exists(p)) throw File.Exists(p) ? NotADirectory(p) : NotFound(p);
                Directory.Delete(p, recursive: true);
            }
            catch (Exception) when (ignore_errors) { }
        }

        static void RemoveTreeWithHandler(string root, object? onexc, object? onerror)
        {
            bool TryOperation(Type module, string operation, string path, Action perform, bool ignoreMissing = false)
            {
                try { perform(); return true; }
                catch (System.IO.FileNotFoundException) when (ignoreMissing) { return false; }
                catch (Exception error) when (error is IOException or UnauthorizedAccessException)
                {
                    using var handling = Builtins.__handling_exception(error);
                    object? method = Builtins.getattr(PyModule.Of(module, module == typeof(os_.path) ? "os.path" : "os"), operation);
                    if (onexc != null) Builtins.__invoke(onexc, [method, path, error]);
                    else Builtins.__invoke(onerror, [method, path, sys_.exc_info()]);
                    return false;
                }
            }

            void RemoveDirectory(string directory)
            {
                string[] contents = Array.Empty<string>();
                TryOperation(typeof(os_), "scandir", directory, () => contents = Directory.GetFileSystemEntries(directory), ignoreMissing: true);
                foreach (string child in contents)
                {
                    if (!IsLink(child) && Directory.Exists(child)) RemoveDirectory(child);
                    else TryOperation(typeof(os_), "unlink", child, () => os_.unlink(child), ignoreMissing: true);
                }
                TryOperation(typeof(os_), "rmdir", directory, () => os_.rmdir(directory), ignoreMissing: true);
            }

            if (!TryOperation(typeof(os_), "lstat", root, () => os_.lstat(root))) return;
            if (!TryOperation(typeof(os_.path), "islink", root, () =>
            {
                if (IsLink(root)) throw new IOException("Cannot call rmtree on a symbolic link");
            })) return;
            RemoveDirectory(root);
        }

        /// <summary>move: renames when it can, else copies and deletes; into a directory under the source's name.</summary>
        public static string move(object src, object dst, Func<string, string, string>? copy_function = null)
        {
            string s = P(src), d = P(dst), realDst = d;
            if (Directory.Exists(d))
            {
                if (SameFile(s, d) && !IsLink(s)) { Directory.Move(s, d); return d; }
                realDst = Globber.PathJoin(d, Basename(s));
                if (Exists(realDst)) throw new Error($"Destination path '{realDst}' already exists");
            }
            if (!Exists(s) && !IsLink(s)) throw NotFound(s);
            try
            {
                if (Directory.Exists(s) && !IsLink(s))
                {
                    string full = System.IO.Path.GetFullPath(s).TrimEnd(System.IO.Path.DirectorySeparatorChar) + System.IO.Path.DirectorySeparatorChar;
                    if (System.IO.Path.GetFullPath(realDst).StartsWith(full, StringComparison.Ordinal))
                        throw new Error($"Cannot move a directory '{s}' into itself '{d}'.");
                    Directory.Move(s, realDst);
                }
                else File.Move(s, realDst, overwrite: true);
            }
            catch (IOException e) when (!(e is Error))
            {
                if (Directory.Exists(s))
                {
                    copytree(s, realDst, symlinks: true, copy_function: copy_function);
                    rmtree(s);
                }
                else
                {
                    (copy_function ?? ((a, b) => copy2(a, b)))(s, realDst);
                    File.Delete(s);
                }
            }
            return realDst;
        }

        // ── the system ──

        /// <summary>which: the path of an executable found on PATH (or None).</summary>
        public static string? which(object cmd, long mode = 1, string? path = null)
        {
            var (dirname, name) = Globber.Split(P(cmd));
            List<string> dirs;
            if (dirname.Length > 0) dirs = new List<string> { dirname };
            else
            {
                path ??= Environment.GetEnvironmentVariable("PATH") ?? "/bin:/usr/bin";
                if (path.Length == 0) return null;
                dirs = path.Split(System.IO.Path.PathSeparator).ToList();
                if (OperatingSystem.IsWindows()) dirs.Insert(0, ".");
            }
            var files = new List<string> { name };
            if (OperatingSystem.IsWindows())
            {
                var exts = (Environment.GetEnvironmentVariable("PATHEXT") ?? ".COM;.EXE;.BAT;.CMD").Split(';', StringSplitOptions.RemoveEmptyEntries);
                if (!exts.Any(e => name.EndsWith(e, StringComparison.OrdinalIgnoreCase))) files = exts.Select(e => name + e).Prepend(name).ToList();
            }
            var seen = new HashSet<string>();
            foreach (var dir in dirs)
            {
                if (!seen.Add(OperatingSystem.IsWindows() ? dir.ToLowerInvariant() : dir)) continue;
                foreach (var f in files)
                {
                    string full = Globber.PathJoin(dir, f);
                    if (File.Exists(full) && Executable(full)) return full;
                }
            }
            return null;
        }

        static bool Executable(string p)
        {
            if (OperatingSystem.IsWindows()) return true;
            const UnixFileMode anyExec = UnixFileMode.UserExecute | UnixFileMode.GroupExecute | UnixFileMode.OtherExecute;
            return (File.GetUnixFileMode(p) & anyExec) != 0;
        }

        /// <summary>disk_usage: total, used and free bytes of the file system holding the path.</summary>
        public static DiskUsage disk_usage(object path)
        {
            string full = System.IO.Path.GetFullPath(P(path));
            if (!Exists(full)) throw NotFound(P(path));
            DriveInfo? best = null;
            foreach (var drive in DriveInfo.GetDrives())
            {
                string root = drive.RootDirectory.FullName;
                bool under = OperatingSystem.IsWindows() ? full.StartsWith(root, StringComparison.OrdinalIgnoreCase)
                           : full == root.TrimEnd('/') || full.StartsWith(root.EndsWith("/") ? root : root + "/", StringComparison.Ordinal);
                if (under && (best == null || root.Length > best.RootDirectory.FullName.Length))
                {
                    try { _ = drive.TotalSize; best = drive; } catch (Exception) { }
                }
            }
            if (best == null) throw new IOException($"[Errno 2] No such file or directory: {Q(P(path))}");
            long total = best.TotalSize, free = best.AvailableFreeSpace, used = total - best.TotalFreeSpace;
            return new DiskUsage(total, used, free);
        }

        /// <summary>get_terminal_size: COLUMNS / LINES, else the terminal's size, else the fallback.</summary>
        public static TerminalSize get_terminal_size((long, long)? fallback = null)
        {
            var (fc, fl) = fallback ?? (80, 24);
            long columns = long.TryParse(Environment.GetEnvironmentVariable("COLUMNS"), out var c) ? c : 0;
            long lines = long.TryParse(Environment.GetEnvironmentVariable("LINES"), out var l) ? l : 0;
            if (columns <= 0 || lines <= 0)
            {
                long sc = fc, sl = fl;
                try { if (!Console.IsOutputRedirected) { sc = Console.WindowWidth; sl = Console.WindowHeight; } } catch (Exception) { }
                if (columns <= 0) columns = sc != 0 ? sc : fc;
                if (lines <= 0) lines = sl != 0 ? sl : fl;
            }
            return new TerminalSize(columns, lines);
        }
    }
